cd /root/.nanobot/media/telegram && awk -F',' 'NR>1 && $2 {
    # 北京时间17-22点 (UTC 09-14)
    split($2, t, "[: .-]")
    if (length(t)>=3) {
        hr = t[4]+0;  # UTC hour
        if (hr >= 9 && hr <= 14) {
            prompt = $8+0
            completion = $9+0
            reasoning = $10+0
            time_ms = $20+0
            ttft = $21+0
